syntax:
For a class, the syntax includes:
- Destructor: ~ClassName() { /* cleanup code, e.g., delete pointers */ }
- Copy Constructor: ClassName(const ClassName& other) { /* deep copy members */ }
- Copy Assignment Operator: ClassName& operator=(const ClassName& other) { /* handle self-assignment, then deep copy */; return *this; }
Practical usage notes: Always check for self-assignment in the assignment operator (if (&other != this) { ... }), and ensure deep copies for resources to prevent issues in multi-threaded or long-lived objects.

code_example:
#include <iostream>
#include <string>

class Book {  // Example from C++ Primer context, like a bookstore item
public:
    Book(const std::string& title) : title(new std::string(title)) {}  // Constructor with dynamic allocation
    Book(const Book& other) : title(new std::string(*other.title)) {}  // Copy constructor for deep copy
    Book& operator=(const Book& other) {  // Assignment operator
        if (this != &other) {  // Check for self-assignment
            delete title;  // Free existing resource
            title = new std::string(*other.title);  // Deep copy
        }
        return *this;
    }
    ~Book() { delete title; }  // Destructor to free resource
    void display() const { std::cout << *title << std::endl; }
private:
    std::string* title;  // Pointer to demonstrate resource management
};

int main() {
    Book book1("C++ Primer");
    Book book2 = book1;  // Invokes copy constructor
    book2.display();
    return 0;
}
